class Solution {
    public int[] vertexDegrees(int[][] matrix) {
        int[] ans = new int[matrix.length];
        for (int i = 0; i < matrix.length; i++) {
            int s = 0;
            for (int j = 0; j < matrix[i].length; j++) s += matrix[i][j];
            ans[i] = s;
        }
        return ans;
    }
}

