class Solution {
public:
    vector<int> vertexDegrees(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<int> ans(n, 0);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                ans[j] += matrix[i][j];
        return ans;
    }
};

